<template><ForgeDialog title="PHP obfuscator" description="Obfuscate a PHP file or folder using an installed PHP runtime." eyebrow="WORKSPACE / SECURITY" wide @close="emit('close')"><div class="ob-panel"><label>PHP runtime<select v-model="runtimeKey"><option value="">Select a runtime</option><option v-for="item in runtimes" :key="item.path+'-'+item.version" :value="item.path+'-'+item.version">PHP {{ item.version }}</option></select></label><label>Source<div class="path-row"><input v-model="source" readonly placeholder="Choose a PHP file or folder" /><button class="action-button" @click="chooseSource">Browse</button></div></label><label>Output<div class="path-row"><input v-model="destination" readonly placeholder="Choose output file or folder" /><button class="action-button" :disabled="!source" @click="chooseDestination">Browse</button></div></label><button class="action-button" @click="showConfig=!showConfig">{{ showConfig?'Hide':'Show' }} configuration</button><textarea v-if="showConfig" v-model="config" rows="6" placeholder="Optional obfuscator configuration" /><p v-if="error" class="forge-alert forge-alert--error">{{ error }}</p><p v-if="done" class="forge-alert">Obfuscation completed successfully.</p><button class="primary-button" :disabled="running||!runtimeKey||!source||!destination" @click="run">{{ running?'Obfuscating…':'Generate obfuscated output' }}</button></div></ForgeDialog></template>
<script setup lang="ts">
import { computed, ref } from 'vue'
import ForgeDialog from './ForgeDialog.vue'
import { BrewStore } from '@/store/brew'
import { dialog, fs, shell } from '@/util/NodeFn'
import IPC from '@/util/IPC'
const emit=defineEmits<{close:[]}>(); const runtimes=computed(()=>BrewStore().module('php').installed.filter((item:any)=>item.enable&&item.num&&item.num>56)); const runtimeKey=ref(''); const source=ref(''); const destination=ref(''); const config=ref(''); const showConfig=ref(false); const running=ref(false); const done=ref(false); const error=ref(''); const chooseSource=async()=>{const r=await dialog.showOpenDialog({properties:['openDirectory','openFile','showHiddenFiles'],filters:[{name:'PHP',extensions:['php']}]});if(!r.canceled&&r.filePaths[0]){source.value=r.filePaths[0];destination.value='';done.value=false}}; const chooseDestination=async()=>{if(!source.value)return;const stat=await fs.stat(source.value);const directory=typeof (stat as any).isDirectory==='function'?(stat as any).isDirectory():Boolean((stat as any).isDirectory);const r=await dialog.showOpenDialog({properties:directory?['openDirectory','createDirectory','showHiddenFiles']:['showHiddenFiles','createDirectory','showOverwriteConfirmation'],filters:directory?undefined:[{name:'PHP',extensions:['php']}]});if(!r.canceled&&r.filePaths[0])destination.value=r.filePaths[0]}; const run=async()=>{const runtime=runtimes.value.find((item:any)=>runtimeKey.value===item.path+'-'+item.version);if(!runtime)return;running.value=true;error.value='';done.value=false;try{await new Promise<void>((resolve,reject)=>{IPC.send('app-fork:php','doObfuscator',{phpversion:runtime.path+'-'+runtime.version,src:source.value,desc:destination.value,config:config.value,bin:(runtime.path+'\\bin\\php')}).then((key:string,res:any)=>{IPC.off(key);res?.code===0?resolve():reject(new Error(res?.msg??'PHP obfuscation failed'))})});done.value=true;await shell.showItemInFolder(destination.value)}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{running.value=false}}
</script>
<style scoped>.ob-panel{display:grid;gap:13px;font-size:12px}.ob-panel label{display:grid;gap:7px;color:var(--pqt-text-muted)}.ob-panel input,.ob-panel select,.ob-panel textarea{width:100%;padding:9px 10px;color:var(--pqt-text);background:var(--pqt-canvas);border:1px solid var(--pqt-border-strong);border-radius:7px;font:11px var(--pqt-font-mono)}.ob-panel textarea{resize:vertical}.path-row{display:flex;gap:8px}.path-row input{flex:1;min-width:0}</style>
